librenms/resources/definitions/os_detect:
os: alfo80hd
text: 'SIAE Alfoplus 80HD'
type: wireless
icon: siae
over:
    - { graph: device_bits, text: Traffic }
    - { graph: device_wireless_rssi, text: RSSI }
    - { graph: device_wireless_power, text: POWER }
discovery:
    - { sysObjectID: .1.3.6.1.4.1.3373.1103, sysDescr: 'ALFOplus80HD - SIAE Microelettronica' }

os: axiscam
text: 'AXIS Network Camera'
type: appliance
icon: axis
mib_dir: axis
discovery:
    -
        sysDescr_regex: '/AXIS .* ((Network|Bullet|PTZ|Dome|Panoramic|Box) Camera|Security Radar|Video (Server|Decoder)|Network Video Encoder|Network Video Intercom|Network Strobe Speaker|Connectivity Hub)/'
over:
    - { graph: device_bits, text: Traffic }
    - { graph: device_processor, text: 'CPU Usage' }
    - { graph: device_mempool, text: 'Memory Usage' }
    - { graph: device_temperature, text: 'Device Temperature' }
    - { graph: device_state, text: 'Device State' }

os: ctm
text: 'Last Mile Gear CTM'
type: wireless
over:
    - { graph: device_temperature, text: Temperature }
    - { graph: device_voltage, text: Voltage }
    - { graph: device_power, text: Power }
    - { graph: device_wireless_clients, text: 'Satellites in View' }
discovery:
    -
        sysObjectID:
            - .1.3.6.1.4.1.25868.

